package com.shipflow.warehouse.api;import com.shipflow.common.api.ApiResponse;import com.shipflow.warehouse.api.model.*;import com.shipflow.warehouse.application.*;import jakarta.validation.Valid;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/orders/{orderId}") public class WarehouseController{private final WarehouseApplicationService s;public WarehouseController(WarehouseApplicationService x){s=x;}@PostMapping("/inbound") public ApiResponse<WarehouseResult> in(@PathVariable Long orderId,@Valid @RequestBody InboundRequest r,@RequestHeader("Idempotency-Key")String k,@RequestHeader(value="X-Request-Id",required=false)String q,@AuthenticationPrincipal Jwt j){return ApiResponse.success(s.inbound(t(j),u(j),orderId,r,k,q));}@PostMapping("/measurements") public ApiResponse<WarehouseResult> me(@PathVariable Long orderId,@Valid @RequestBody MeasurementRequest r,@RequestHeader("Idempotency-Key")String k,@RequestHeader(value="X-Request-Id",required=false)String q,@AuthenticationPrincipal Jwt j){return ApiResponse.success(s.measure(t(j),u(j),orderId,r,k,q));}@PostMapping("/outbound") public ApiResponse<WarehouseResult> out(@PathVariable Long orderId,@Valid @RequestBody OutboundRequest r,@RequestHeader("Idempotency-Key")String k,@RequestHeader(value="X-Request-Id",required=false)String q,@AuthenticationPrincipal Jwt j){return ApiResponse.success(s.outbound(t(j),u(j),orderId,r,k,q));}private Long t(Jwt j){return Long.valueOf(j.getClaimAsString("tenant_id"));}private Long u(Jwt j){return Long.valueOf(j.getSubject());}}
